/// Removes the kᵗʰ element (1-based) from `list`.
///
/// Specification:
///   - Requires 1 ≤ k < list.len()
///   - Ensures the returned vector has length one less than the original
///   - Ensures that all elements before the removed index match
///   - Ensures that all elements after the removed index match (shifted by 1)
#[requires(k >= 1 && k < list.len())]
#[ensures(result.len() == list.len() - 1)]
#[ensures(forall(|i: usize| i < k - 1 ==> result[i] == list[i]))]
#[ensures(forall(|i: usize| k - 1 <= i && i < result.len() ==> result[i] == list[i + 1]))]
fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based and guaranteed 1 <= k < list.len()
    assert!(k >= 1 && k < list.len(), "k out of bounds");

    let idx = k - 1;  // convert to 0-based index
    let mut new_list = Vec::with_capacity(list.len() - 1);

    // extend with all elements before idx
    new_list.extend_from_slice(&list[..idx]);
    // extend with all elements after idx
    new_list.extend_from_slice(&list[idx + 1..]);

    new_list
}

